import random, time
from openai import OpenAI, RateLimitError

client = OpenAI()

def chat(messages, model="gpt-4o-mini", max_retries=4, **kw):
    """Call with retry/backoff + usage logging. The only wrapper you need."""
    for attempt in range(max_retries):
        try:
            return client.chat.completions.create(
                model=model, messages=messages,
                stream_options={"include_usage": True},
                **kw,
            )
        except RateLimitError as e:
            if attempt == max_retries - 1:
                raise
            wait = (2 ** attempt) + random.random()   # backoff + jitter
            ra = e.response.headers.get("Retry-After")
            if ra: wait = float(ra)
            print(f"429 — retry {attempt + 1} in {wait:.1f}s")
            time.sleep(wait)

# --- streaming render ------------------------------------------------
stream = chat(
    [{"role": "user", "content": "Explain chunking in 2 sentences"}],
    stream=True, max_tokens=120,
)
full = ""
for chunk in stream:
    piece = chunk.choices[0].delta.content or ""
    print(piece, end="", flush=True)   # render live
    full += piece
    if chunk.usage:
        print(f"\n[usage] {chunk.usage}")   # tokens for cost logging

